from typing import List, Dict, Any, Optional
from app.schemas.models import CertificateData

def build_matcher_prompt(cert: CertificateData, candidates: List[Dict[str, Any]], user_email: Optional[str] = None, search_results: Optional[List[Dict[str, Any]]] = None) -> str:
    cand_str = "".join([f"\nCandidate Index: {i}\n- Subject: {c.get('subject')}\n- Sender: {c.get('sender')}\n- Date: {c.get('date')}\n- Snippet: {c.get('body', '')[:1000].replace('\n', ' ')}...\n" for i, c in enumerate(candidates)])
    web_str = "### 3. Web Search Context:\n" + "".join([f"- Title: {r.get('title')}\n  Snippet: {r.get('content')}\n" for r in search_results]) if search_results else ""
    return f"You are an expert AI Matcher and Cognitive Document Linking Agent.\nYour task is to match a structured certificate with the single most relevant email from a list of candidate emails.\n\n### 1. Certificate OCR Metadata:\n- **Certificate Name**: {cert.certificate_name}\n- **Recipient**: {cert.recipient}\n- **Issuer / Conducted By**: {cert.issuer}\n- **Date**: {cert.date}\n- **Skills**: {', '.join(cert.skills) if cert.skills else 'None'}\n- **Target Recipient Email**: {user_email or 'None provided'}\n\n### 2. Candidate Email List:\n{cand_str}\n\n{web_str}\n\n### Matching Rules:\n1. Find if ANY email matches this certificate (course confirmations, delivery, acceptances, proof of publications, awards, etc.).\n2. High similarity in certificate name/synonyms is required. Issuer matching sender domain is a strong indicator, but not strictly required if the email subject/body strongly matches the certificate name and context.\n3. If no email candidates match, return `matched_index: -1`.\n4. Prioritize accuracy. Do not force a match if there is no strong contextual evidence.\n\n### Required Output Format:\nYour output MUST be a strict, single JSON object:\n{{\n  \"matched_index\": 0, // Best matching email index, or -1\n  \"reason\": \"Concise 1-2 sentence explanation of why this matches\",\n  \"matching_confidence\": 0.95 // Float between 0.0 and 1.0\n}}"
